using ChartForgeX;
using ChartForgeX.Core;
using ChartForgeX.Primitives;
var chart = Chart.Create().WithTitle("Selected service status").WithSubtitle("95 selected services").WithSize(1200, 400).WithXLabels("Healthy", "Attention", "Offline").WithYAxis("Services").WithYAxisBounds(0, 100).WithLegend(false).WithDataLabels(true).AddBar("Services", new[] { new ChartPoint(1, 84), new ChartPoint(2, 8), new ChartPoint(3, 3) });
chart.SavePng(args[0]);
chart.SaveSvg(args[1]);
